-- Class notes synopsis batch 13: Guayusa through Holy Basil

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Guayusa</strong> is a <strong>stimulant nervine</strong> and caffeine-bearing plant used for <strong>energy</strong> and <strong>mental clarity</strong>.$$
WHERE id = 2574;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Guduchi</strong> (Tinospora cordifolia) is an <strong>anti-inflammatory</strong>, <strong>immune amphoteric</strong>, and <strong>alterative</strong> herb - cooling and well-suited for hot, irritated people or those sensitive to surroundings and overstimulated by everything. It helps with <strong>gout</strong>, <strong>liver disease</strong>, and <strong>arthritis</strong>, and inhibits <strong>insulin resistance</strong> while supporting <strong>blood lipid metabolism</strong>. Tincture dose: 1:5, 1.5-2.5 ml TID.$$
WHERE id = 18;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Guggul</strong> (Commiphora mukul, also known as Mukul myrrh) appears in the Jill Stansbury Hashimoto's formula alongside <a href="?herb=118"><strong>Bladderwrack</strong></a>, <a href="?herb=78"><strong>Licorice</strong></a>, <a href="?herb=14"><strong>Panax Ginseng</strong></a>, and <a href="?herb=31"><strong>Blue Flag</strong></a> (Iris versicolor) - equal parts, 1-2 dropperfuls 3-5x/day for months.$$
WHERE id = 877;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Gumweed</strong> is a <strong>decongestant</strong> indicated for <strong>asthma</strong> and <strong>allergic reactions</strong>.$$
WHERE id = 199;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Gymnema</strong> (Gymnema sylvestre) increases insulin levels rather than enhancing insulin sensitivity; used for <strong>type 1 and type 2 insulin-dependent diabetes</strong> - lowers blood sugar levels, improves <strong>glycemic control</strong>, and reduces A1C levels; not ideal for pure <strong>insulin resistance</strong>. Paired with <a href="?herb=167"><strong>Cinnamon</strong></a> and <a href="?herb=2556"><strong>Bitter Melon</strong></a> for <strong>Type 2 Diabetes</strong>; also combined with <a href="?herb=2556"><strong>Bitter Melon</strong></a> for <strong>blood sugar regulation</strong>. <strong>Avoid or use cautiously for type 1 diabetes - Gymnema increases insulin levels rather than enhancing insulin sensitivity.</strong>$$
WHERE id = 2232;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Hawthorn</strong> berry is a <strong>sour</strong>, <strong>cooling</strong>, <strong>astringent</strong> <strong>cardiotonic</strong> and <strong>nervine</strong>; tonifies tissues, protects against <strong>oxidative stress</strong>, and supports the <strong>liver</strong>; a source of <strong>Vitamin C</strong> and flavonoids. As a <strong>cardiotonic</strong>, berries act directly on the <strong>heart muscle</strong> - supporting <strong>myocardium</strong> contraction, regulating the heart's beat, moderating <strong>hypertension</strong>, and toning the heart; a <strong>CV tonic</strong> that strengthens the vasculature, lowers blood pressure, and is helpful for <strong>arrhythmia</strong> and <strong>atherosclerosis</strong>. Also a <strong>relaxing nervine</strong> for <strong>anxiety</strong> and heart and chest tightness - paired with <a href="?herb=131"><strong>Motherwort</strong></a> for heart and chest anxiety; calming for <strong>ADHD</strong>. A spirit remedy for courage and strength of the heart - indicated for <strong>depression</strong> from heartbreak or grief. Indicated for <strong>erectile dysfunction</strong>, <strong>infertility</strong> (circulatory support), and as a <strong>circulatory stimulant</strong> for wet constitution. Used in <strong>pregnancy</strong> as a first-line decoction for blood pressure to avoid <strong>preeclampsia</strong> / gestational hypertension; ingredient (1 tbsp berries) in Iron Tonic Syrup for pregnancy. Cold infusion for <strong>excitability in children</strong> - described as for "sweaty little cherries." In the Deep Lung Formula for <strong>bronchitis</strong> alongside <a href="?herb=54"><strong>Elecampane</strong></a>, <a href="?herb=65"><strong>Angelica</strong></a>, <a href="?herb=590"><strong>Yerba Santa</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=61"><strong>Mullein</strong></a>, <a href="?herb=309"><strong>Yerba Mansa</strong></a>, <a href="?herb=21"><strong>Garlic</strong></a>, and <a href="?herb=104"><strong>Osha</strong></a>; also for <strong>asthma</strong> (<strong>anti-inflammatory</strong> and <strong>cardiotonic</strong>) and <strong>emphysema</strong> (with <a href="?herb=131"><strong>Motherwort</strong></a>); both <strong>nervine</strong> and <strong>circulatory stimulant</strong> - supporting blood flow underlying lung gas exchange when circulation is part of the respiratory picture. Heart decoction recipe (32 oz water): 28g Hawthorn berries, 28g <a href="?herb=849"><strong>Rose Hips</strong></a>, 14g <a href="?herb=167"><strong>Cinnamon</strong></a>. Optional cardiovascular add-in with <a href="?herb=57"><strong>Elder</strong></a> (elderberry) to a base of <a href="?herb=2233"><strong>Hibiscus</strong></a> Red Drank. Combined with <a href="?herb=134"><strong>Lemon Balm</strong></a>, <a href="?herb=2233"><strong>Hibiscus</strong></a>, and <a href="?herb=16"><strong>Rhodiola</strong></a> for clarity and calmness in body. Tincture preparation: alcohol absorbs phytochemicals more fully but can be dry and hot, not tolerated by all; glycerite may improve compliance; option to add tincture to water or use spirits (50-60%), with longer infusing time than 95%. Note: not native to North America - good for colder climates. <strong>Caution for patients with bradycardia (low heart rate) - Hawthorn not recommended.</strong>$$
WHERE id = 73;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Hawthorn</strong> leaf and flower is considered the best physical herb for the heart - <strong>sweet</strong>, <strong>sour</strong>, <strong>astringent</strong>, <strong>cooling</strong>; high in flavonoid <strong>rutin</strong>; acts on the <strong>vasculature</strong> (as opposed to <a href="?herb=73"><strong>Hawthorn berries</strong></a> which act on the heart muscle); as a <strong>cardiotonic</strong>, regulates the heart's beat, moderates <strong>hypertension</strong>, and tones the heart; opens up the <strong>coronary arteries</strong> and supports cardiac tissue. Decreases anxiety; for restlessness, irritability, and nervousness from the heart; a shen disturbance herb, good for <strong>ADHD</strong>; normalizes <strong>cholesterol</strong> levels; for <strong>stomach</strong> and <strong>GI disorders</strong> in TCM. Flowers especially noted for <strong>grief</strong> - used in tonic tincture for grief and heart support (can use physical and spirit doses). Used in calming blends for <strong>hypertension</strong> alongside <a href="?herb=90"><strong>Linden</strong></a> and <a href="?herb=131"><strong>Motherwort</strong></a>; part of the Heart Formula glycerite with <a href="?herb=2233"><strong>Hibiscus</strong></a>, <a href="?herb=90"><strong>Linden</strong></a>, and <a href="?herb=124"><strong>Ginger</strong></a>. Included in a calming sleep tincture (2P <a href="?herb=145"><strong>Valerian</strong></a>, 1P <a href="?herb=128"><strong>California Poppy</strong></a>, 1/2 Hawthorn L+F, 1/2 <a href="?herb=13"><strong>Holy Basil</strong></a>, 1/2 <a href="?herb=45"><strong>Marshmallow</strong></a>, 1/2 <a href="?herb=167"><strong>Cinnamon</strong></a>) and in the traditional Hibiscus Refresher with <a href="?herb=2233"><strong>Hibiscus</strong></a>, clove, <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=124"><strong>Ginger</strong></a>, and orange peel.$$
WHERE id = 1652;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Helichrysum</strong> is a <strong>vulnerary</strong> used in <strong>wound wash</strong> and in a salve with <a href="?herb=89"><strong>Comfrey</strong></a> for <strong>skin healing only</strong> - used after the antimicrobial treatment phase is complete.$$
WHERE id = 831;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Hibiscus</strong> (Hibiscus sabdariffa) is <strong>sour</strong>, <strong>cooling</strong>, and <strong>astringent</strong> with actions including <strong>anti-inflammatory</strong>, <strong>antioxidant</strong>, <strong>antimicrobial</strong>, <strong>antiviral</strong>, <strong>cardiotonic</strong>, <strong>cardioprotective</strong>, <strong>cholesterol-lowering</strong>, <strong>GI tonic</strong>, <strong>anticancer</strong>, <strong>diuretic</strong>, <strong>demulcent</strong>, <strong>hypotensive</strong>, and <strong>hepatic</strong>; rich in fruit acids, flavonoids, anthocyanins, and <strong>Vitamin C</strong>. A <strong>nutritive</strong> herb high in magnesium with affinity for <strong>heart health</strong> (electrical contraction); acts like an <strong>ACE inhibitor</strong> via the angiotensin process - lowers blood pressure through <strong>vasodilation</strong> and <strong>diuretic</strong> reduction of blood volume; part of the Heart Formula glycerite with <a href="?herb=90"><strong>Linden</strong></a>, <a href="?herb=1652"><strong>Hawthorn leaf and flower</strong></a>, and <a href="?herb=124"><strong>Ginger</strong></a>. Anthocyanins stimulate <strong>myogenesis</strong> and muscle protein synthesis, protect against muscle degradation; supports <strong>hyaluronic acid</strong> production in the extracellular matrix, prevents hyaluronidase expansion - excellent for <strong>metabolic disorders</strong> and tissue degradation (<strong>PCOS</strong>/<strong>PMOS</strong>); tissue nourishment alongside <a href="?herb=45"><strong>Marshmallow</strong></a>. Antioxidant for <strong>thyroid health</strong>; also lowers blood sugar - as a lukewarm infusion, selected for blood sugar case study; paired with <a href="?herb=167"><strong>Cinnamon</strong></a>, <a href="?herb=2232"><strong>Gymnema</strong></a>, and <a href="?herb=2556"><strong>Bitter Melon</strong></a> for <strong>Type 2 Diabetes</strong>. Also an <strong>emmenagogue</strong> and <strong>appetite suppressant</strong>; used seasonally when temps shift hotter. Cold infusion is full of slimy <strong>mucilage</strong>; <strong>mucilage is damaged by heat</strong> - however, good in decoction if not seeking the mucilage; also used as <strong>wound wash</strong>. Pairs well with okra for <strong>bladder and urinary</strong> assistance (hibiscus hot decoction, 30 min, steep several hours). Included in regenerative tea blend with <a href="?herb=151"><strong>Horsetail</strong></a>, <a href="?herb=95"><strong>Corn Silk</strong></a>, <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=44"><strong>Yarrow</strong></a>, <a href="?herb=1014"><strong>Lady's Mantle</strong></a>, and <a href="?herb=42"><strong>Red Clover</strong></a>. Used for stroke recovery (hypertension, atrial fibrillation, stage 4 CKD) alongside <a href="?herb=43"><strong>Nettle</strong></a>, <a href="?herb=28"><strong>Cleavers</strong></a>, and <a href="?herb=178"><strong>Oat Straw</strong></a> - herbs taken at midday, meds morning and evening. Red Drank / Hibiscus Refresher: hibiscus decoction (2 x 30 min, combined and reduced) with <a href="?herb=124"><strong>Ginger</strong></a>, clove, <a href="?herb=167"><strong>Cinnamon</strong></a>, honey, orange peel, and <a href="?herb=1652"><strong>Hawthorn leaf and flower</strong></a> - cardiovascular and appetite-suppressing beverage. <strong>Check for low blood pressure before using.</strong>$$
WHERE id = 2233;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Holy Basil</strong> (Tulsi, Ocimum tenuiflorum) is a <strong>warming adaptogen</strong> - soft, uplifting, and grounding; also a <strong>carminative</strong>, <strong>nervine</strong>, and mild <strong>antiviral</strong>. Supports the <strong>HPA axis</strong>, modulates immune function, lowers cortisol (alongside <a href="?herb=9"><strong>Siberian Ginseng</strong></a> and <a href="?herb=14"><strong>Ginseng</strong></a>); a gentle choice for <strong>stress</strong>, <strong>anxiety</strong>, and <strong>adrenal support</strong> without over-stimulating - though like <a href="?herb=14"><strong>Panax Ginseng</strong></a> and <a href="?herb=16"><strong>Rhodiola</strong></a>, can overdo it if already running on empty (supports adapting and change, not giving extra energy). Used for <strong>stagnant depression</strong> - uplifting yet grounding; especially for depression with <strong>blood sugar dysregulation</strong>, <strong>brain fog</strong>, or <strong>stomach issues</strong>; for <strong>ADHD</strong> (focus and adaptogenic support); nervous system support in <strong>food sensitivity</strong> context, specific to constitution; adaptogen for accumulation with aging. Grounding yet heart-opening - not like <a href="?herb=145"><strong>Valerian</strong></a>; air of beauty, <strong>aphrodisiac</strong> quality; helps dispel brain fog in gut and brain; centered in cold infusion; tinctured with glycerin to maintain aromatics; fresh tincture is incredible and dries well. Rosmarinic acid-rich - supports <strong>methylation</strong> and <strong>estrogen metabolism</strong> in <strong>fibroids</strong>; specific for <strong>hyperthyroidism</strong> via rosmarinic acid - calms uptake of T3 into tissues; hyperthyroid picture: underweight, high metabolism, can cause dryness leading to inflammatory states; glucose-regulating for <strong>thyroid health</strong>; gently cooling to overactive thyroid. Used in primary absorption tincture for <strong>thyroid</strong>/<strong>Hashimoto's</strong> alongside <a href="?herb=17"><strong>Schizandra</strong></a>, <a href="?herb=20"><strong>Ashwagandha</strong></a>, <a href="?herb=206"><strong>Milk Thistle</strong></a>, and <a href="?herb=109"><strong>Rosemary</strong></a>. Regulates blood sugar; improves blood sugar levels and blood sugar metabolism in <strong>PMOS</strong>; used in <strong>PCOS</strong> formulas; combined with <a href="?herb=2556"><strong>Bitter Melon</strong></a>, <a href="?herb=15"><strong>American Ginseng</strong></a>, <a href="?herb=167"><strong>Cinnamon</strong></a>, and <a href="?herb=158"><strong>Barberry</strong></a> for <strong>insulin resistance</strong>. For cold constitution: <strong>hormone balancer</strong>, tissue protective in face of microbes, toxins, and stress, nourishing to <strong>reproductive organs</strong>. Supports <strong>skin and nails</strong>; ingredient in "Sleepy Horsey" tea for calm, clear mind and tranquilizing sleep with <a href="?herb=84"><strong>Chamomile</strong></a>, <a href="?herb=82"><strong>Lavender</strong></a>, and <a href="?herb=151"><strong>Horsetail</strong></a>. Mildly uplifting nervine combined with <a href="?herb=134"><strong>Lemon Balm</strong></a> and <a href="?herb=136"><strong>Catnip</strong></a>; in hot-to-cold infusion with <a href="?herb=178"><strong>Oat Straw</strong></a> (3 pts) and <a href="?herb=134"><strong>Lemon Balm</strong></a> (1 pt); in stress tincture at equal parts with <a href="?herb=9"><strong>Siberian Ginseng</strong></a> for anxiety and emotional support. Suggested addition to calming blend for <strong>hypertension</strong> with <a href="?herb=90"><strong>Linden</strong></a>, <a href="?herb=1652"><strong>Hawthorn leaf and flower</strong></a>, and <a href="?herb=131"><strong>Motherwort</strong></a>. <strong>Contraindicated with hypothyroidism - avoid in severe hypothyroidism (cooling to thyroid).</strong>$$
WHERE id = 13;
